    w(f"| energy per group read (full array) | a = 8: near {en['i_macro_a8_near_far_A'][0]*5*0.1*(0.5e-9-en['tau_s'])*1e12:.2f} pJ, far {en['i_macro_a8_near_far_A'][1]*5*0.1*(0.5e-9-en['tau_s'])*1e12:.2f} pJ per 0.5 ns pulse (+ 0.35 pJ word line per active row x a) | [SIM]; scales with T |")
    w(f"| array latency per group read | 0.13-0.16 ns (settle), sample at 200 ps; + sense stage [TBD] | [SIM] |")
